From 941d050c04bae583f363cfdc6f650c03607d7cdc Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:18:49 +0100
Subject: [PATCH] applets/dict: look up pasted words right away

Pasting a word into the Dictionary widget did nothing until Enter was
pressed. When several characters arrive at once, as with paste, middle
click or drop, the word is now looked up immediately; typing is unchanged.

BUG: 515039
---
 applets/dict/qml/main.qml | 15 ++++++++++++++-
 1 file changed, 14 insertions(+), 1 deletion(-)

diff --git a/applets/dict/qml/main.qml b/applets/dict/qml/main.qml
index a41c9c219..b948ba36f 100644
--- a/applets/dict/qml/main.qml
+++ b/applets/dict/qml/main.qml
@@ -72,7 +72,10 @@ PlasmoidItem {
                 placeholderText: i18nc("@info:placeholder", "Enter word to define here…")
                 Layout.fillWidth: true
                 Layout.minimumWidth: Kirigami.Units.gridUnit * 12
-                onAccepted: {
+                property int previousLength: 0
+                property int previousSelectionLength: 0
+
+                function define() {
                     if (input.text === "") {
                         web.visible = false;
                         placeholder.opacity = 0;
@@ -82,6 +85,16 @@ PlasmoidItem {
                         dict.lookup(input.text);
                     }
                 }
+
+                onAccepted: define()
+                onTextChanged: {
+                    // Look up right away when several characters arrive at once (paste, middle click, drop)
+                    if (text.length > previousLength - previousSelectionLength + 1) {
+                        define();
+                    }
+                    previousLength = text.length;
+                }
+                onSelectedTextChanged: previousSelectionLength = selectedText.length
             }
             PlasmaComponents3.Button {
                 id: configureButton
-- 
